const ELEMENT_PROP_KEYS = new Set(["theme","value","label","steps","snapGap","stagger","accent","fontFamily","ink","background","scale","delay","grain","speed"]);

const ELEMENT_PROP_DEFAULTS: Record<string, unknown> = {
  theme: "dark",
  value: "4 hours",
  label: "back, every week",
  steps: 4,
  snapGap: 12,
  stagger: 3,
  accent: "#3B5BFD",
  fontFamily: "Instrument Sans",
  scale: 1,
  delay: 0,
  grain: true,
  speed: 1,
};

type StemStretchElementProps = InteractiveBaseProps &
  InteractiveTransformProps &
  ComponentProps<typeof StemStretchBase>;

const StemStretchInner = forwardRef<
  HTMLDivElement,
  StemStretchElementProps & { readonly controls: SequenceControls | undefined }
>(({ controls, name, style, ...rest }, ref) => {
  const outlineRef = useRef<HTMLDivElement>(null);
  useImperativeHandle(ref, () => outlineRef.current as HTMLDivElement, []);
  const componentProps: Record<string, unknown> = { ...ELEMENT_PROP_DEFAULTS };
  const sequenceProps: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(rest)) {
    if (ELEMENT_PROP_KEYS.has(key)) {
      if (value !== undefined) componentProps[key] = value;
    } else {
      sequenceProps[key] = value;
    }
  }
  return (
    <Sequence
      layout="none"
      {...sequenceProps}
      controls={controls}
      name={name ?? "<StemStretch>"}
      outlineRef={outlineRef}
    >
      <div
        ref={outlineRef}
        style={{
          position: "relative",
          width: "100%",
          height: "100%",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          ...style,
        }}
      >
        <StemStretchBase
          {...(componentProps as unknown as ComponentProps<typeof StemStretchBase>)}
        />
      </div>
    </Sequence>
  );
});

export const StemStretch = Interactive.withSchema({
  Component: StemStretchInner,
  componentName: "<StemStretch>",
  componentIdentity: null,
  schema: elementSchema,
  supportsEffects: false,
});
